#[test]
fn frozen_v041_matches_literal_prior_binary_bytes() {
    use super::frozen::Snapshot;
    use crate::session::afk::delegation::hash;
    for (bytes, expected) in [
        (
            IMPORT,
            "644787c82e846a27579003d47c37add375bdcebf9edf08d4a9d0457a25084c53",
        ),
        (
            NO_BUDGET,
            "ec486e27ac713d0c1ab0d8c54b6ed6ede778a031f5338835212023f9b20fa582",
        ),
        (
            QUESTION,
            "6bde24e4b19e8c3c65c0cba7a0526fb04d1f8a2e4c010e3ac4b519b25bf1ee35",
        ),
    ] {
        assert_eq!(hash(bytes), expected);
        let snapshot: Snapshot = serde_json::from_str(bytes).unwrap();
        snapshot.validate(&snapshot.profile).unwrap();
        assert_eq!(serde_json::to_vec(&snapshot).unwrap(), bytes.as_bytes());
    }
}
